import{_ as r,a0 as i,w as s,s as m,ao as p,I as o,a1 as a,A as n,x as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"直擊 Elementart OS 0.3 Freya - 下載和安裝指南 | LCTT x X-CMD","titleTemplate":false,"description":"直擊 Elementart OS 0.3 Freya - 下載和安裝指南 | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"直擊 Elementart OS 0.3 Freya - 下載和安裝指南 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"直擊 Elementart OS 0.3 Freya - 下載和安裝指南 | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150413 Elementary OS 0.3 Freya Screenshots - Download and Install Guide","title":"直擊 Elementart OS 0.3 Freya - 下載和安裝指南","tag":"201504","desc":""},"relativePath":"201504/20150413 Elementary OS 0.3 Freya Screenshots - Download and Install Guide.md","filePath":"[post].md"}'),d={name:"201504/20150413 Elementary OS 0.3 Freya Screenshots - Download and Install Guide.md"};function u(g,t,y,S,f,b){const l=i("Link");return s(),m("div",null,[t[18]||(t[18]=p('<h1 id="直擊-elementart-os-0-3-freya-下載和安裝指南" tabindex="-1">直擊 Elementart OS 0.3 Freya - 下載和安裝指南 <a class="header-anchor" href="#直擊-elementart-os-0-3-freya-下載和安裝指南" aria-label="Permalink to “直擊 Elementart OS 0.3 Freya - 下載和安裝指南”">​</a></h1><p>Elementary OS是一個以Ubuntu為基礎的輕量級操作系統，廣受歡迎。目前已經發行了三個版本，而第四個版本將會以即將到來的Ubuntu16.04為基礎開發。</p><ul><li><strong>Jupiter (0.1)</strong>: 第一個Elementary OS穩定發行版基於Ubuntu 10.10，在2011年三月發佈。</li><li><strong>Luna (0.2)</strong>: Elementary OS第二個穩定發行版基於Ubuntu 12.04，於2012年11月發佈。</li><li><strong>Freya (0.3)</strong>: Elementary OS第三個穩定發行版基於Ubuntu 14.04的，2015年二月8號發佈。</li><li><strong>Loki (0.4)</strong>: 未來Elementary OS第四版，計劃以Ubuntu16.04為基礎，並且提供更新服務直到2021年。</li></ul><p>Freya是目前最新的Elementary OS版本（0.3）。最初是被命名為ISIS，但是後來改了，是為了避免與同名的恐怖組織產生任何的聯繫。Freya有一些非常不錯的預裝應用。</p><h3 id="突出的特性" tabindex="-1">突出的特性 <a class="header-anchor" href="#突出的特性" aria-label="Permalink to “突出的特性”">​</a></h3><p>這裏列舉了一些特性，但並非Elementary OS 0.3的所有特性。</p><ul><li>更好的交互性消息通知，可在通知設定面板設定系統級別的“Do Not Disturb（不要打擾）”模式。</li><li>最新版Elementary OS提供更好的emoji表情支持，及內置替換了網頁應用中的微軟核心字體。</li><li>Privacy模式是一個新的防火牆工具，易於使用，可以幫助保護電腦免遭惡意腳本和應用的攻擊。</li><li>統一風格的登入和鎖定界面。</li><li>改進了界面效果和功能的應用中心菜單，包括快速操作列表，搜索拖放，支持快速數學計算。</li><li>重新設計的多任務視圖提供更多以應用為中心的功能。</li><li>更新了軟件棧（Linux 3.16， Gtk 3.14 和Vala 0.26），更好的支持和增強了最新開發的應用。</li><li>UEFI支持。</li><li>通過新的聯網助手，WiFi連接變得更容易。</li></ul><h3 id="下載64位-32位版本" tabindex="-1">下載64位&amp;32位版本 <a class="header-anchor" href="#下載64位-32位版本" aria-label="Permalink to “下載64位&amp;32位版本”">​</a></h3>',8)),o("ul",null,[o("li",null,[a(l,{href:"http://sourceforge.net/projects/elementaryos/files/stable/elementaryos-freya-amd64.20150411.iso/download"},{default:n(()=>[...t[0]||(t[0]=[e("Elementary OS Freya 64 bit",-1)])]),_:1})]),o("li",null,[a(l,{href:"http://sourceforge.net/projects/elementaryos/files/stable/elementaryos-freya-i386.20150411.iso/download"},{default:n(()=>[...t[1]||(t[1]=[e("Elementary OS Freya 32 bit",-1)])]),_:1})])]),t[19]||(t[19]=p(`<h3 id="安裝elementary-os-0-3-freya" tabindex="-1">安裝Elementary OS 0.3 (Freya) <a class="header-anchor" href="#安裝elementary-os-0-3-freya" aria-label="Permalink to “安裝Elementary OS 0.3 (Freya)”">​</a></h3><p>下載Elementary OS 0.3的ISO文件，並且寫入到一個USB啓動盤或者DVD/CD。支持32位和64位的架構。當計算機從Elementary OS ISO文件啓動後，有兩個選項可用，或不安裝而僅試用，或直接安裝到計算機裏。這裏選擇第二項。Elmentary OS也可以與已有操作系統並存安裝，構成雙重啓動。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/Install-Freya.png" alt="Install Freya"></p><p>在進行下面的步驟之前會檢查系統要求和資源有效性。如果你的系統有足夠的資源，點擊繼續。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/Installation-Requirements.png" alt="Installation Requirements"></p><p>安裝嚮導提供許多安裝形式。選取最適合你的選項，通常大多數都選用第一個選項：“擦除磁盤以安裝Elementary”。選擇該選項，必須保證你的原有數據都已經正確備份了，因為磁盤（分區）將會被擦除，其上所有的數據將會丟失。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/Installation-Types.png" alt="Installation Types"></p><p>接下來的對話框顯示了Elementary OS所使用和需要格式化的磁盤分區列表，確保數據完整後點擊繼續。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/Format-Warning.png" alt="Format Warning"></p><p>選擇你的地理位置，確定時區，點擊繼續。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/Location.png" alt="Location"></p><p>選擇你的語言，點擊繼續。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/Language.png" alt="Language"></p><p>填入你的信息，選擇一個高強度的超級用户/管理員密碼，點擊繼續。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/whoareyou.png" alt="whoareyou"></p><p>當你的信息提供後，核心安裝進程就會啓動，正在安裝的組件的詳細信息會在一個小對話框裏隨進度條一閃而過。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/Installation-progress.png" alt="Installation progress"></p><p>恭喜你！最新的Elementary OS 0.3 (Freya)已經安裝完成了。此時需要重啓來更新和完整註冊，恭喜。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/Installation-Complet.png" alt="Installation Complet"></p><p>啓動時，Elementary OS將顯示它優雅的logo，然後會出現密碼保護的管理員登入和遊客訪問選項。遊客訪問有相當多的限制功能，而且沒有安裝軟件的權限。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/Login.png" alt="Login"></p><p>下圖是新安裝的Elementary OS 0.3的畫面。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/first-look.png" alt="first look"></p><h3 id="個性化桌面" tabindex="-1">個性化桌面 <a class="header-anchor" href="#個性化桌面" aria-label="Permalink to “個性化桌面”">​</a></h3><p>Elementary OS 0.3以其輕巧和美觀而為我們熟知，每個人有自己獨特的審美觀和計算機使用習慣。桌面反映出每一個計算機使用者的個人偏好。如其他操作系統一樣，Elementary OS 0.3也提供了許多選項來個性化配置桌面，包括壁紙，字體大小，主題等等。</p><p>基本的個性化配置，點擊Applications &gt; System Settings &gt; Desktop</p><p>我們可以改變壁紙，泊板（dock）和啓用桌面熱角。</p><p>默認提供了很少的壁紙，更多的可以從網上下載或者從你的相機傳輸過來。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/Desktop-Wallpaper4.png" alt="Desktop Wallpaper"></p><p>Elementary OS真正的美麗在於優雅的泊板。桌面上沒有任何圖標，泊板上的應用圖標顯示逼真，通過它可以快速訪問常用應用。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/Desktop-Dock1.png" alt="Desktop Dock"></p><p>用户可以定製桌面的四個角的功能。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/Hot-Corners.png" alt="Hot Corners"></p><p>通過安裝elementary tweaks工具來更深入的個性化定製。</p><p>可以使用如下命令，將穩定的個人軟件包檔案（PPA）添加到高級軟件包管理工具（APT）倉庫。</p><pre><code>sudo add-apt-repository ppa:mpstark/elementary-tweaks-daily
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/elementary-tweaks-ppa.png" alt="ppa"></p><p>一旦軟件包添加到倉庫後，我們需要用以下命令更新倉庫</p><pre><code>sudo apt-get update
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/update-repository.png" alt="update repository"></p><p>更新倉庫後，我們就可以安裝elementary-tweaks，用以下命令完成</p><pre><code>sudo apt-get install elementary-tweaks
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/install-elementary-tweaks.png" alt="install elementary tweaks"></p><p>我們可以在Application &gt; System Settings下的個人區域的看到增加了一個Tweaks項目。它現在可以給我們提供更多的個性化定製選項。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/tweaks.png" alt="tweaks"></p><p>為了進一步定製，我們也安裝了gnome桌面系統的tweak工具，演示解鎖桌面。</p><pre><code>sudo apt-get install gnome-tweak-tool
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/04/gnome.png" alt="gnome"></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3>`,49)),o("p",null,[t[3]||(t[3]=e("Elementary OS十分接近Linux發行版Ubuntu，它的優缺點兩方面也都十分相似。Elementary OS在外觀和體驗上都十分輕巧和優雅，並且正在快速地走向成熟。它有潛力成為Windows和OS X操作系統之外的第三選擇。最新的Elementary OS 0.3（Freya）以其良好的功能基礎而迅速流行。想了解更多信息，最近的更新和下載，請訪問其官方",-1)),a(l,{href:"http://sourceforge.net/projects/elementaryos/files/stable/elementaryos-freya-amd64.20150411.iso/download"},{default:n(()=>[...t[2]||(t[2]=[e("網站",-1)])]),_:1}),t[4]||(t[4]=e("。",-1))]),t[20]||(t[20]=o("hr",null,null,-1)),o("p",null,[t[6]||(t[6]=e("via: ",-1)),a(l,{href:"http://linoxide.com/ubuntu-how-to/elementary-os-0-3-freya-install-guide/"},{default:n(()=>[...t[5]||(t[5]=[e("http://linoxide.com/ubuntu-how-to/elementary-os-0-3-freya-install-guide/",-1)])]),_:1})]),o("p",null,[t[10]||(t[10]=e("作者：",-1)),a(l,{href:"http://linoxide.com/author/arunrz/"},{default:n(()=>[...t[7]||(t[7]=[e("Aun Raza",-1)])]),_:1}),t[11]||(t[11]=e(" 譯者：",-1)),a(l,{href:"https://github.com/wi-cuckoo"},{default:n(()=>[...t[8]||(t[8]=[e("wi-cuckoo",-1)])]),_:1}),t[12]||(t[12]=e(" 校對：",-1)),a(l,{href:"https://github.com/wxy"},{default:n(()=>[...t[9]||(t[9]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[15]||(t[15]=e("本文由 ",-1)),a(l,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[13]||(t[13]=[e("LCTT",-1)])]),_:1}),t[16]||(t[16]=e(" 原創翻譯，",-1)),a(l,{href:"http://linux.cn/"},{default:n(()=>[...t[14]||(t[14]=[e("Linux中國",-1)])]),_:1}),t[17]||(t[17]=e(" 榮譽推出",-1))])])}const x=r(d,[["render",u]]);export{h as __pageData,x as default};
